 15→// changeTree represents pending changes to apply to a git tree incrementally.
 16→// Only changed paths are traversed; unchanged subtrees are reused by hash reference.
 17→type changeTree struct {
 18→	dirs  map[string]*changeTree // subdirectory changes
 19→	files map[string]*fileChange // file changes in this directory
 20→}
 21→
 22→// fileChange represents a single file addition, update, or deletion.
 23→type fileChange struct {
 24→	hash   plumbing.Hash
 25→	mode   filemode.FileMode
 26→	delete bool
 27→}
 28→
 29→func newChangeTree() *changeTree {
 30→	return &changeTree{
 31→		dirs:  make(map[string]*changeTree),
 32→		files: make(map[string]*fileChange),
 33→	}
 34→}
 35→
 36→// addFile records a file addition or update in the change tree.
 37→// The path uses forward slashes as separators (git convention).
 38→func (ct *changeTree) addFile(path string, hash plumbing.Hash, mode filemode.FileMode) {
 39→	parts := strings.Split(path, "/")
 40→	node := ct
 41→	for _, part := range parts[:len(parts)-1] {
 42→		if _, ok := node.dirs[part]; !ok {
 43→			node.dirs[part] = newChangeTree()
 44→		}
 45→		node = node.dirs[part]
 46→	}
 47→	node.files[parts[len(parts)-1]] = &fileChange{hash: hash, mode: mode}
 48→}
 49→
 50→// deleteFile records a file deletion in the change tree.
 51→func (ct *changeTree) deleteFile(path string) {
 52→	parts := strings.Split(path, "/")
 53→	node := ct
 54→	for _, part := range parts[:len(parts)-1] {
 55→		if _, ok := node.dirs[part]; !ok {
 56→			node.dirs[part] = newChangeTree()
 57→		}
 58→		node = node.dirs[part]
 59→	}
 60→	node.files[parts[len(parts)-1]] = &fileChange{delete: true}
 61→}
 62→
 63→// isEmpty returns true if the change tree has no pending changes.
 64→func (ct *changeTree) isEmpty() bool {
 65→	return len(ct.dirs) == 0 && len(ct.files) == 0
 66→}
 67→
 68→// applyChangesToTree merges a changeTree into a base git tree, returning the new root tree hash.
 69→// Only directories containing changes are rebuilt; unchanged subtrees are reused by hash reference.
 70→// This is O(changed_files * tree_depth) instead of O(total_files_in_repo).
 71→func applyChangesToTree(repo *git.Repository, baseTreeHash plumbing.Hash, changes *changeTree) (plumbing.Hash, error) {
 72→	if changes.isEmpty() {
 73→		return baseTreeHash, nil
 74→	}
 75→
 76→	baseTree, err := repo.TreeObject(baseTreeHash)
 77→	if err != nil {
 78→		return plumbing.ZeroHash, fmt.Errorf("failed to get tree: %w", err)
 79→	}
 80→
 81→	// Track which change entries we've processed (matched to existing tree entries)
 82→	processedDirs := make(map[string]bool)
 83→	processedFiles := make(map[string]bool)
 84→
 85→	var newEntries []object.TreeEntry
 86→
 87→	// Process existing entries
 88→	for _, entry := range baseTree.Entries {
 89→		if entry.Mode == filemode.Dir {
 90→			if dirChanges, ok := changes.dirs[entry.Name]; ok {
 91→				// Recurse into subdirectory with changes
 92→				newSubHash, subErr := applyChangesToTree(repo, entry.Hash, dirChanges)
 93→				if subErr != nil {
 94→					return plumbing.ZeroHash, subErr
 95→				}
 96→				newEntries = append(newEntries, object.TreeEntry{
 97→					Name: entry.Name,
 98→					Mode: filemode.Dir,
 99→					Hash: newSubHash,
100→				})
101→				processedDirs[entry.Name] = true
102→			} else if fileChange, ok := changes.files[entry.Name]; ok {
103→				// Type conflict: base has dir, changes has file → replace dir with file
104→				if !fileChange.delete {
105→					newEntries = append(newEntries, object.TreeEntry{
106→						Name: entry.Name,
107→						Mode: fileChange.mode,
108→						Hash: fileChange.hash,
109→					})
110→				}
111→				processedFiles[entry.Name] = true
112→			} else {
113→				// No changes in this directory, keep as-is
114→				newEntries = append(newEntries, entry)
115→			}
116→		} else {
117→			// File entry
118→			if change, ok := changes.files[entry.Name]; ok {
119→				if !change.delete {
120→					newEntries = append(newEntries, object.TreeEntry{
121→						Name: entry.Name,
122→						Mode: change.mode,
123→						Hash: change.hash,
124→					})
125→				}
126→				// If delete: don't add to newEntries
127→				processedFiles[entry.Name] = true
128→			} else if dirChanges, ok := changes.dirs[entry.Name]; ok {
129→				// Type conflict: base has file, changes has dir → replace file with dir
130→				newSubHash, subErr := createTreeFromChanges(repo, dirChanges)
131→				if subErr != nil {
132→					return plumbing.ZeroHash, subErr
133→				}
134→				if newSubHash != plumbing.ZeroHash {
135→					newEntries = append(newEntries, object.TreeEntry{
136→						Name: entry.Name,
137→						Mode: filemode.Dir,
138→						Hash: newSubHash,
139→					})
140→				}
141→				processedDirs[entry.Name] = true
142→			} else {
143→				// No change, keep as-is
144→				newEntries = append(newEntries, entry)
145→			}
146→		}
147→	}
148→
149→	// Add new files (not in base tree)
150→	for name, change := range changes.files {
151→		if !processedFiles[name] && !change.delete {
152→			newEntries = append(newEntries, object.TreeEntry{
153→				Name: name,
154→				Mode: change.mode,
155→				Hash: change.hash,
156→			})
157→		}
158→	}
159→
160→	// Add new directories (not in base tree)
161→	for name, dirChanges := range changes.dirs {
162→		if !processedDirs[name] {
163→			newSubHash, subErr := createTreeFromChanges(repo, dirChanges)
164→			if subErr != nil {
165→				return plumbing.ZeroHash, subErr
166→			}
167→			// Skip empty trees (e.g., all changes were deletions for non-existent paths)
168→			if newSubHash == plumbing.ZeroHash {
169→				continue
170→			}
171→			newEntries = append(newEntries, object.TreeEntry{
172→				Name: name,
173→				Mode: filemode.Dir,
174→				Hash: newSubHash,
175→			})
176→		}
177→	}
178→
179→	sortTreeEntries(newEntries)
180→	return storeTree(repo, newEntries)
181→}
182→
183→// createTreeFromChanges creates a new tree from a changeTree with no base tree.
184→// Used for new directories that don't exist in the base tree.
185→func createTreeFromChanges(repo *git.Repository, changes *changeTree) (plumbing.Hash, error) {
186→	var entries []object.TreeEntry
187→
188→	for name, change := range changes.files {
189→		if !change.delete {
190→			entries = append(entries, object.TreeEntry{
191→				Name: name,
192→				Mode: change.mode,
193→				Hash: change.hash,
194→			})
195→		}
196→	}
197→
198→	for name, dirChanges := range changes.dirs {
199→		subHash, err := createTreeFromChanges(repo, dirChanges)
200→		if err != nil {
201→			return plumbing.ZeroHash, err
202→		}
203→		// Skip empty subtrees (all files were deletions)
204→		if subHash == plumbing.ZeroHash {
205→			continue
206→		}
207→		entries = append(entries, object.TreeEntry{
208→			Name: name,
209→			Mode: filemode.Dir,
210→			Hash: subHash,
211→		})
212→	}
213→
214→	// If all entries were deletions, don't create an empty tree
215→	if len(entries) == 0 {
216→		return plumbing.ZeroHash, nil
217→	}
218→
219→	sortTreeEntries(entries)
220→	return storeTree(repo, entries)
221→}
222→
223→// storeTree creates and stores a git tree object from entries.
224→func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
225→	tree := &object.Tree{Entries: entries}
226→	obj := repo.Storer.NewEncodedObject()
227→	if err := tree.Encode(obj); err != nil {
228→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
229→	}
230→	hash, err := repo.Storer.SetEncodedObject(obj)
231→	if err != nil {
232→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
233→	}
234→	return hash, nil
235→}
