237→// addDirectoryToChangeTree walks a filesystem directory and adds all files to a changeTree.
238→// dirPathAbs is the absolute path for reading files, dirPathRel is the git tree path prefix.
239→func addDirectoryToChangeTree(repo *git.Repository, dirPathAbs, dirPathRel string, ct *changeTree) error {
240→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, walkErr error) error {
241→		if walkErr != nil {
242→			return walkErr
243→		}
244→		if info.IsDir() {
245→			return nil
246→		}
247→
248→		relWithinDir, relErr := filepath.Rel(dirPathAbs, path)
249→		if relErr != nil {
250→			return fmt.Errorf("failed to get relative path for %s: %w", path, relErr)
251→		}
252→
253→		blobHash, mode, blobErr := createBlobFromFile(repo, path)
254→		if blobErr != nil {
255→			return fmt.Errorf("failed to create blob for %s: %w", path, blobErr)
256→		}
257→
258→		// Use forward slashes for git tree paths
259→		treePath := filepath.ToSlash(dirPathRel) + "/" + filepath.ToSlash(relWithinDir)
260→		ct.addFile(treePath, blobHash, mode)
261→		return nil
262→	})
263→	if err != nil {
264→		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
265→	}
266→	return nil
267→}
