328→// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
329→// It parses the main transcript from startLine, extracts spawned agent IDs,
330→// and calculates their token usage from transcripts in subagentsDir.
331→func CalculateTotalTokenUsage(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
332→	if transcriptPath == "" {
333→		return &agent.TokenUsage{}, nil
334→	}
335→
336→	// Parse transcript ONCE
337→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
338→	if err != nil {
339→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
340→	}
341→
342→	return CalculateTotalTokenUsageFromLines(parsed, subagentsDir)
343→}
344→
345→// CalculateTotalTokenUsageFromLines calculates token usage from pre-parsed transcript lines,
346→// including subagents. This avoids re-parsing the transcript file when lines have already been parsed.
347→// Subagent transcripts are still read from subagentsDir.
348→func CalculateTotalTokenUsageFromLines(parsed []TranscriptLine, subagentsDir string) (*agent.TokenUsage, error) {
349→	// Calculate token usage from parsed transcript
350→	mainUsage := CalculateTokenUsage(parsed)
351→
352→	// Extract spawned agent IDs from the same parsed transcript
353→	agentIDs := ExtractSpawnedAgentIDs(parsed)
354→
355→	// Calculate subagent token usage
356→	if len(agentIDs) > 0 {
357→		subagentUsage := &agent.TokenUsage{}
358→		for agentID := range agentIDs {
359→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
360→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
361→			if err != nil {
362→				// Agent transcript may not exist yet or may have been cleaned up
363→				continue
364→			}
365→			subagentUsage.InputTokens += agentUsage.InputTokens
366→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
367→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
368→			subagentUsage.OutputTokens += agentUsage.OutputTokens
369→			subagentUsage.APICallCount += agentUsage.APICallCount
370→		}
371→		if subagentUsage.APICallCount > 0 {
372→			mainUsage.SubagentTokens = subagentUsage
373→		}
374→	}
375→
376→	return mainUsage, nil
377→}
