379→// ExtractAllModifiedFiles extracts files modified by both the main agent and
380→// any subagents spawned via the Task tool. It parses the main transcript from
381→// startLine, collects modified files from the main agent, then reads each
382→// subagent's transcript from subagentsDir to collect their modified files too.
383→// The result is a deduplicated list of all modified file paths.
384→func ExtractAllModifiedFiles(transcriptPath string, startLine int, subagentsDir string) ([]string, error) {
385→	if transcriptPath == "" {
386→		return nil, nil
387→	}
388→
389→	// Parse main transcript once
390→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
391→	if err != nil {
392→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
393→	}
394→
395→	return ExtractAllModifiedFilesFromLines(parsed, subagentsDir)
396→}
397→
398→// ExtractAllModifiedFilesFromLines extracts files modified by both the main agent and
399→// any subagents spawned via the Task tool, using pre-parsed transcript lines.
400→// This avoids re-parsing the transcript file when lines have already been parsed.
401→// Subagent transcripts are still read from subagentsDir.
402→func ExtractAllModifiedFilesFromLines(parsed []TranscriptLine, subagentsDir string) ([]string, error) {
403→	// Collect modified files from main agent
404→	fileSet := make(map[string]bool)
405→	var files []string
406→	for _, f := range ExtractModifiedFiles(parsed) {
407→		if !fileSet[f] {
408→			fileSet[f] = true
409→			files = append(files, f)
410→		}
411→	}
412→
413→	// Find spawned subagents and collect their modified files
414→	agentIDs := ExtractSpawnedAgentIDs(parsed)
415→	for agentID := range agentIDs {
416→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
417→		agentLines, _, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
418→		if agentErr != nil {
419→			// Subagent transcript may not exist yet or may have been cleaned up
420→			continue
421→		}
422→		for _, f := range ExtractModifiedFiles(agentLines) {
423→			if !fileSet[f] {
424→				fileSet[f] = true
425→				files = append(files, f)
426→			}
427→		}
428→	}
429→
430→	return files, nil
431→}
