 15→// ParseFromBytes parses transcript content from a byte slice.
 16→// Uses bufio.Reader to handle arbitrarily long lines.
 17→func ParseFromBytes(content []byte) ([]Line, error) {
 18→	var lines []Line
 19→	reader := bufio.NewReader(bytes.NewReader(content))
 20→
 21→	for {
 22→		lineBytes, err := reader.ReadBytes('\n')
 23→		if err != nil && err != io.EOF {
 24→			return nil, fmt.Errorf("failed to read transcript: %w", err)
 25→		}
 26→
 27→		// Handle empty line or EOF without content
 28→		if len(lineBytes) == 0 {
 29→			if err == io.EOF {
 30→				break
 31→			}
 32→			continue
 33→		}
 34→
 35→		var line Line
 36→		if err := json.Unmarshal(lineBytes, &line); err == nil {
 37→			lines = append(lines, line)
 38→		}
 39→
 40→		if err == io.EOF {
 41→			break
 42→		}
 43→	}
 44→
 45→	return lines, nil
 46→}
 47→
 48→// ParseFromFileAtLine reads and parses a transcript file starting from a specific line.
 49→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
 50→// Returns:
 51→//   - lines: parsed transcript lines from startLine onwards (malformed lines skipped)
 52→//   - totalLines: total number of lines in the file (including malformed ones)
 53→//   - error: any error encountered during reading
 54→//
 55→// The startLine parameter is 0-indexed (startLine=0 reads from the beginning).
 56→// This is useful for incremental parsing when you've already processed some lines.
 57→func ParseFromFileAtLine(path string, startLine int) ([]Line, int, error) {
 58→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
 59→	if err != nil {
 60→		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
 61→	}
 62→	defer func() { _ = file.Close() }()
 63→
 64→	var lines []Line
 65→	reader := bufio.NewReader(file)
 66→
 67→	totalLines := 0
 68→	for {
 69→		lineBytes, err := reader.ReadBytes('\n')
 70→		if err != nil && err != io.EOF {
 71→			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
 72→		}
 73→
 74→		// Handle empty line or EOF without content
 75→		if len(lineBytes) == 0 {
 76→			if err == io.EOF {
 77→				break
 78→			}
 79→			continue
 80→		}
 81→
 82→		// Count all lines for totalLines, but only parse after startLine
 83→		if totalLines >= startLine {
 84→			var line Line
 85→			if err := json.Unmarshal(lineBytes, &line); err == nil {
 86→				lines = append(lines, line)
 87→			}
 88→		}
 89→		totalLines++
 90→
 91→		if err == io.EOF {
 92→			break
 93→		}
 94→	}
 95→
 96→	return lines, totalLines, nil
 97→}
 98→
 99→// CountLines counts the number of lines in a transcript file without parsing JSON.
100→// This is much faster than ParseFromFileAtLine when only the line count is needed.
101→func CountLines(path string) (int, error) {
102→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
103→	if err != nil {
104→		return 0, fmt.Errorf("failed to open transcript: %w", err)
105→	}
106→	defer func() { _ = file.Close() }()
107→
108→	count := 0
109→	buf := make([]byte, 32*1024)
110→	for {
111→		n, readErr := file.Read(buf)
112→		for i := range n {
113→			if buf[i] == '\n' {
114→				count++
115→			}
116→		}
117→		if readErr == io.EOF {
118→			break
119→		}
120→		if readErr != nil {
121→			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
122→		}
123→	}
124→	return count, nil
125→}
126→
127→// SliceFromLine returns the content starting from line number `startLine` (0-indexed).
128→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
129→// For example, if startLine is 2, lines 0 and 1 are skipped and the result starts at line 2.
130→// Returns empty slice if startLine exceeds the number of lines.
131→func SliceFromLine(content []byte, startLine int) []byte {
132→	if len(content) == 0 || startLine <= 0 {
133→		return content
134→	}
135→
136→	// Find the byte offset where startLine begins
137→	lineCount := 0
138→	offset := 0
139→	for i, b := range content {
140→		if b == '\n' {
141→			lineCount++
142→			if lineCount == startLine {
143→				offset = i + 1
144→				break
145→			}
146→		}
147→	}
148→
149→	// If we didn't find enough lines, return empty
150→	if lineCount < startLine {
151→		return nil
152→	}
153→
154→	// If offset is beyond content, return empty
155→	if offset >= len(content) {
156→		return nil
157→	}
158→
159→	return content[offset:]
160→}
161→
162→// ExtractUserContent extracts user content from a raw message.
163→// Handles both string and array content formats.
164→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
165→// Returns empty string if the message cannot be parsed or contains no text.
166→func ExtractUserContent(message json.RawMessage) string {
167→	var msg UserMessage
168→	if err := json.Unmarshal(message, &msg); err != nil {
169→		return ""
170→	}
171→
172→	// Handle string content
173→	if str, ok := msg.Content.(string); ok {
174→		return textutil.StripIDEContextTags(str)
175→	}
176→
177→	// Handle array content (only if it contains text blocks)
178→	if arr, ok := msg.Content.([]interface{}); ok {
179→		var texts []string
180→		for _, item := range arr {
181→			if m, ok := item.(map[string]interface{}); ok {
182→				if m["type"] == ContentTypeText {
183→					if text, ok := m["text"].(string); ok {
184→						texts = append(texts, text)
185→					}
186→				}
187→			}
188→		}
189→		if len(texts) > 0 {
190→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
191→		}
192→	}
193→
194→	return ""
195→}
