 53→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 54→// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 55→// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 56→// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 57→// are correctly treated as new.
 58→func (s *PrePromptState) PreUntrackedFiles() []string {
 59→	if s == nil {
 60→		return nil
 61→	}
 62→	if s.UntrackedFiles == nil {
 63→		return []string{}
 64→	}
 65→	return s.UntrackedFiles
 66→}
