 68→// normalizePrePromptState migrates deprecated fields after loading from JSON.
 69→func (s *PrePromptState) normalizePrePromptState() {
 70→	// Migrate the oldest field to the intermediate field first
 71→	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 72→		s.StepTranscriptStart = s.LastTranscriptLineCount
 73→	}
 74→	s.LastTranscriptLineCount = 0
 75→
 76→	// Migrate all deprecated fields to the unified TranscriptOffset
 77→	if s.TranscriptOffset == 0 {
 78→		if s.StepTranscriptStart > 0 {
 79→			s.TranscriptOffset = s.StepTranscriptStart
 80→		} else if s.StartMessageIndex > 0 {
 81→			s.TranscriptOffset = s.StartMessageIndex
 82→		}
 83→	}
 84→	s.StepTranscriptStart = 0
 85→	s.StartMessageIndex = 0
