 88→// CapturePrePromptState captures current untracked files and transcript position before a prompt
 89→// and saves them to a state file.
 90→//
 91→// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
 92→// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
 93→// The sessionRef parameter is optional — if empty, transcript position won't be captured.
 94→//
 95→// Works correctly from any subdirectory within the repository.
 96→func CapturePrePromptState(ag agent.Agent, sessionID, sessionRef, userPrompt string) error {
 97→	if sessionID == "" {
 98→		sessionID = unknownSessionID
 99→	}
100→
101→	// Get absolute path for tmp directory
102→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
103→	if err != nil {
104→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
105→	}
106→
107→	// Create tmp directory if it doesn't exist
108→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
109→		return fmt.Errorf("failed to create tmp directory: %w", err)
110→	}
111→
112→	// Get list of untracked files (excluding .entire directory itself)
113→	untrackedFiles, err := getUntrackedFilesForState()
114→	if err != nil {
115→		return fmt.Errorf("failed to get untracked files: %w", err)
116→	}
117→
118→	// Get transcript position using TranscriptAnalyzer if available
119→	var transcriptOffset int
120→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok && sessionRef != "" {
121→		pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
122→		if posErr != nil {
123→			fmt.Fprintf(os.Stderr, "Warning: failed to get transcript position: %v\n", posErr)
124→		} else {
125→			transcriptOffset = pos
126→		}
127→	}
128→
129→	// Create state file
130→	stateFile := prePromptStateFile(sessionID)
131→	state := PrePromptState{
132→		SessionID:        sessionID,
133→		Timestamp:        time.Now().UTC().Format(time.RFC3339),
134→		UntrackedFiles:   untrackedFiles,
135→		UserPrompt:       userPrompt,
136→		TranscriptOffset: transcriptOffset,
137→	}
138→
139→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
140→	if err != nil {
141→		return fmt.Errorf("failed to marshal state: %w", err)
142→	}
143→
144→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
145→		return fmt.Errorf("failed to write state file: %w", err)
146→	}
147→
148→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript offset: %d\n",
149→		len(untrackedFiles), transcriptOffset)
150→	return nil
151→}
