160→	}
161→
162→	data, err := os.ReadFile(stateFile) //nolint:gosec // Reading from controlled git metadata path
163→	if err != nil {
164→		return nil, fmt.Errorf("failed to read state file: %w", err)
165→	}
166→
167→	var state PrePromptState
168→	if err := json.Unmarshal(data, &state); err != nil {
169→		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
170→	}
171→
172→	state.normalizePrePromptState()
173→
174→	return &state, nil
