322→// FilterAndNormalizePaths converts absolute paths to relative and filters out
323→// infrastructure paths and paths outside the repo.
324→func FilterAndNormalizePaths(files []string, cwd string) []string {
325→	var result []string
326→	for _, file := range files {
327→		relPath := paths.ToRelativePath(file, cwd)
328→		if relPath == "" {
329→			continue // outside repo
330→		}
331→		if paths.IsInfrastructurePath(relPath) {
332→			continue // skip .entire directory
333→		}
334→		result = append(result, relPath)
335→	}
336→	return result
337→}
