410→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
411→	}
412→
413→	// Create tmp directory if it doesn't exist
414→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
415→		return fmt.Errorf("failed to create tmp directory: %w", err)
416→	}
417→
418→	// Get list of untracked files (excluding .entire directory itself)
419→	untrackedFiles, err := getUntrackedFilesForState()
420→	if err != nil {
421→		return fmt.Errorf("failed to get untracked files: %w", err)
422→	}
423→
424→	// Create state file
425→	stateFile := preTaskStateFile(toolUseID)
426→	state := PreTaskState{
427→		ToolUseID:      toolUseID,
428→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
429→		UntrackedFiles: untrackedFiles,
430→	}
431→
432→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
433→	if err != nil {
434→		return fmt.Errorf("failed to marshal state: %w", err)
435→	}
436→
437→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
438→		return fmt.Errorf("failed to write state file: %w", err)
439→	}
440→
441→	fmt.Fprintf(os.Stderr, "Captured state before task: %d untracked files\n", len(untrackedFiles))
442→	return nil
443→}
