537→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
538→// It counts existing checkpoint files in the task metadata checkpoints directory.
539→// Returns 1 if no checkpoints exist yet.
540→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
541→	// Use the session ID directly as the metadata directory name
542→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
543→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
544→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
545→
546→	entries, err := os.ReadDir(checkpointsDir)
547→	if err != nil {
548→		// Directory doesn't exist or can't be read - start at 1
549→		return 1
550→	}
551→
552→	// Count JSON files (checkpoints)
553→	count := 0
554→	for _, entry := range entries {
555→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
556→			count++
557→		}
558→	}
559→
560→	return count + 1
561→}
