 19→// Transcript message type constants - aliases to transcript package for local use.
 20→const (
 21→	transcriptTypeUser      = transcript.TypeUser
 22→	transcriptTypeAssistant = transcript.TypeAssistant
 23→	contentTypeText         = transcript.ContentTypeText
 24→	contentTypeToolUse      = transcript.ContentTypeToolUse
 25→)
 26→
 27→// PromptResponsePair represents a user prompt and the assistant's responses.
 28→// Used for extracting all interactions from a transcript.
 29→type PromptResponsePair struct {
 30→	Prompt    string
 31→	Responses []string // Multiple responses can occur between tool calls
 32→	Files     []string
 33→}
 34→
 35→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
 36→// Returns pairs in chronological order (oldest first).
 37→// Each pair contains the user's prompt, assistant's text response, and files modified.
 38→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
 39→	var pairs []PromptResponsePair
 40→
 41→	// Find all user prompts (messages with string content, not tool results)
 42→	var userIndices []int
 43→	for i, line := range transcript {
 44→		if line.Type == transcriptTypeUser {
 45→			var msg userMessage
 46→			if err := json.Unmarshal(line.Message, &msg); err != nil {
 47→				continue
 48→			}
 49→			// Only count messages with string content (real user prompts)
 50→			if _, ok := msg.Content.(string); ok {
 51→				userIndices = append(userIndices, i)
 52→			} else if arr, ok := msg.Content.([]interface{}); ok {
 53→				// Check if array has text blocks (also a real user prompt)
 54→				for _, item := range arr {
 55→					if m, ok := item.(map[string]interface{}); ok {
 56→						if m["type"] == contentTypeText {
 57→							userIndices = append(userIndices, i)
 58→							break
 59→						}
 60→					}
 61→				}
 62→			}
 63→		}
 64→	}
 65→
 66→	// For each user prompt, extract the prompt text, following assistant response, and files
 67→	for idx, userIdx := range userIndices {
 68→		// Determine the range for this prompt's conversation
 69→		endIdx := len(transcript)
 70→		if idx < len(userIndices)-1 {
 71→			endIdx = userIndices[idx+1]
 72→		}
 73→
 74→		// Extract prompt text
 75→		prompt := extractUserPromptAt(transcript, userIdx)
 76→		if prompt == "" {
 77→			continue
 78→		}
 79→
 80→		// Extract assistant responses and files from this range
 81→		slice := transcript[userIdx:endIdx]
 82→		responses := extractAssistantResponses(slice)
 83→		files := extractModifiedFiles(slice)
 84→
 85→		pairs = append(pairs, PromptResponsePair{
 86→			Prompt:    prompt,
 87→			Responses: responses,
 88→			Files:     files,
 89→		})
 90→	}
 91→
 92→	return pairs
 93→}
 94→
 95→// extractUserPromptAt extracts the user prompt at the given index.
 96→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
 97→func extractUserPromptAt(lines []transcriptLine, idx int) string {
 98→	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
 99→		return ""
100→	}
101→
102→	return transcript.ExtractUserContent(lines[idx].Message)
103→}
104→
105→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
106→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
107→func extractAssistantResponses(transcript []transcriptLine) []string {
108→	var texts []string
109→	for _, line := range transcript {
110→		if line.Type == transcriptTypeAssistant {
111→			var msg assistantMessage
112→			if err := json.Unmarshal(line.Message, &msg); err != nil {
113→				continue
114→			}
115→
116→			for _, block := range msg.Content {
117→				if block.Type == contentTypeText && block.Text != "" {
118→					texts = append(texts, block.Text)
119→				}
120→			}
121→		}
122→	}
123→	return texts
124→}
125→
126→// extractUserPrompts extracts all user messages from the transcript in order.
127→// Only considers messages with string content (not tool results).
128→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
129→func extractUserPrompts(transcript []transcriptLine) []string {
130→	var prompts []string
131→	for i := range transcript {
132→		if transcript[i].Type != transcriptTypeUser {
133→			continue
134→		}
135→		var msg userMessage
136→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
137→			continue
138→		}
139→
140→		// Handle string content
141→		if str, ok := msg.Content.(string); ok {
142→			prompts = append(prompts, textutil.StripIDEContextTags(str))
143→			continue
144→		}
145→
146→		// Handle array content (only if it contains text blocks)
147→		if arr, ok := msg.Content.([]interface{}); ok {
148→			var texts []string
149→			for _, item := range arr {
150→				if m, ok := item.(map[string]interface{}); ok {
151→					if m["type"] == contentTypeText {
152→						if text, ok := m["text"].(string); ok {
153→							texts = append(texts, text)
154→						}
155→					}
156→				}
157→			}
158→			if len(texts) > 0 {
159→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
160→			}
161→		}
162→	}
163→	return prompts
164→}
165→
166→// extractLastUserPrompt extracts the last user message from the transcript.
167→// Only considers messages with string content (not tool results).
168→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
169→func extractLastUserPrompt(transcript []transcriptLine) string {
170→	prompts := extractUserPrompts(transcript)
171→	if len(prompts) == 0 {
172→		return ""
173→	}
174→	return prompts[len(prompts)-1]
175→}
176→
177→// findLastUserUUID finds the UUID of the last user message (that has string content)
178→func findLastUserUUID(transcript []transcriptLine) string {
179→	for i := len(transcript) - 1; i >= 0; i-- {
180→		if transcript[i].Type == transcriptTypeUser {
181→			var msg userMessage
182→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
183→				continue
184→			}
185→			// Only count messages with string content (not tool results)
186→			if _, ok := msg.Content.(string); ok {
187→				return transcript[i].UUID
188→			}
189→		}
190→	}
191→	return ""
192→}
193→
194→// filterTranscriptAfterUUID returns transcript lines after the given UUID
195→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
196→	if uuid == "" {
197→		return transcript
198→	}
199→
200→	foundIndex := -1
201→	for i, line := range transcript {
202→		if line.UUID == uuid {
203→			foundIndex = i
204→			break
205→		}
206→	}
207→
208→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
209→		return transcript
210→	}
211→
212→	return transcript[foundIndex+1:]
213→}
214→
215→// extractModifiedFiles extracts the list of files modified by tool calls
216→func extractModifiedFiles(transcript []transcriptLine) []string {
217→	fileSet := make(map[string]bool)
218→	var files []string
219→
220→	for _, line := range transcript {
221→		if line.Type == transcriptTypeAssistant {
222→			var msg assistantMessage
223→			if err := json.Unmarshal(line.Message, &msg); err != nil {
224→				continue
225→			}
226→
227→			for _, block := range msg.Content {
228→				if block.Type == contentTypeToolUse {
229→					isModifyTool := false
230→					for _, name := range claudecode.FileModificationTools {
231→						if block.Name == name {
232→							isModifyTool = true
233→							break
234→						}
235→					}
236→
237→					if isModifyTool {
238→						var input toolInput
239→						if err := json.Unmarshal(block.Input, &input); err != nil {
240→							continue
241→						}
242→
243→						file := input.FilePath
244→						if file == "" {
245→							file = input.NotebookPath
246→						}
247→
248→						if file != "" && !fileSet[file] {
249→							fileSet[file] = true
250→							files = append(files, file)
251→						}
252→					}
253→				}
254→			}
255→		}
256→	}
257→
258→	return files
259→}
