261→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
262→// Computes the path dynamically from the current repo location for cross-machine portability.
263→func resolveTranscriptPath(sessionID string, agent agentpkg.Agent) (string, error) {
264→	repoRoot, err := paths.RepoRoot()
265→	if err != nil {
266→		return "", fmt.Errorf("failed to get repository root: %w", err)
267→	}
268→
269→	sessionDir, err := agent.GetSessionDir(repoRoot)
270→	if err != nil {
271→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
272→	}
273→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
274→}
