363→// TranscriptPosition contains the position information for a transcript file.
364→type TranscriptPosition struct {
365→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
366→	LineCount int    // Total number of lines
367→}
368→
369→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
370→// Returns empty position if file doesn't exist or is empty.
371→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
372→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
373→	if path == "" {
374→		return TranscriptPosition{}, nil
375→	}
376→
377→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
378→	if err != nil {
379→		if os.IsNotExist(err) {
380→			return TranscriptPosition{}, nil
381→		}
382→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
383→	}
384→	defer func() { _ = file.Close() }()
385→
386→	var pos TranscriptPosition
387→	reader := bufio.NewReader(file)
388→
389→	for {
390→		lineBytes, err := reader.ReadBytes('\n')
391→		if err != nil && err != io.EOF {
392→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
393→		}
394→
395→		if len(lineBytes) == 0 {
396→			if err == io.EOF {
397→				break
398→			}
399→			continue
400→		}
401→
402→		pos.LineCount++
403→
404→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
405→		var line transcriptLine
406→		if err := json.Unmarshal(lineBytes, &line); err == nil {
407→			if line.UUID != "" {
408→				pos.LastUUID = line.UUID
409→			}
410→		}
411→
412→		if err == io.EOF {
413→			break
414→		}
415→	}
416→
417→	return pos, nil
418→}
